import{C as n,o as r,c as t,a2 as l,E as d,j as e,a as u,t as c,p as m}from"./chunks/framework.D21_4UK8.js";const p={class:"rock-copy-email-wrapper inline"},f=JSON.parse('{"title":"Acerca de - Main St Audio Labs","description":"","frontmatter":{"layout":"doc","sidebar":false,"aside":false,"title":"Acerca de - Main St Audio Labs"},"headers":[],"relativePath":"es/about.md","filePath":"es/about.md"}'),b={name:"es/about.md"},q=Object.assign(b,{setup(g){const o=m("Copiar Correo");function i(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),o.value="¡Copiado!",setTimeout(function(){o.value="Copiar Correo"},2e3)}return(y,a)=>{const s=n("NewsletterSubscribe");return r(),t("div",null,[a[1]||(a[1]=l('<h1 id="acerca-de-main-st-audio-labs" tabindex="-1">Acerca de Main St Audio Labs <a class="header-anchor" href="#acerca-de-main-st-audio-labs" aria-label="Permalink to &quot;Acerca de Main St Audio Labs&quot;">​</a></h1><p>Main St Audio Labs es un proyecto personal nacido en la intersección de la pasión por el rock &#39;n&#39; roll vintage, el modelado analógico y la ingeniería de software.</p><hr><h2 id="la-historia-detras-del-laboratorio" tabindex="-1">La Historia Detrás del Laboratorio <a class="header-anchor" href="#la-historia-detras-del-laboratorio" aria-label="Permalink to &quot;La Historia Detrás del Laboratorio&quot;">​</a></h2><p>Main St Audio Labs fue fundado por <strong>Emiliano Tegli</strong>, desarrollador de audio independiente, guitarrista y entusiasta del tono, obsesionado con los sonidos de guitarra crudos, dinámicos y sensibles al tacto de finales de los años 60 y principios de los 70.</p><p>El nombre es un tributo directo a las legendarias sesiones en el sótano del <em>Exile on Main St.</em> de los Rolling Stones, una era en la que los discos eran grasientos, las válvulas se empujaban hasta su punto de fusión y los tonos de guitarra tenían una calidez orgánica y tridimensional que definió la música rock.</p><hr><h2 id="¿por-que-main-st-audio-labs" tabindex="-1">¿Por qué Main St Audio Labs? <a class="header-anchor" href="#¿por-que-main-st-audio-labs" aria-label="Permalink to &quot;¿Por qué Main St Audio Labs?&quot;">​</a></h2><p>Los plugins de audio modernos se han vuelto increíblemente potentes, pero a menudo se interponen en el camino de la creación musical. Los músicos y productores se ven frecuentemente obligados a navegar por parámetros infinitos, coordinar enrutamientos complejos, desplazarse por cientos de ajustes preestablecidos y lidiar con configuraciones infladas que agotan los recursos de la CPU.</p><p>Creemos en un enfoque diferente: <strong>El Manifiesto de la Simplicidad.</strong></p><h3 id="_1-calibrado-a-las-grabaciones-originales-listo-para-mezcla" tabindex="-1">1. Calibrado a las Grabaciones Originales (Listo para Mezcla) <a class="header-anchor" href="#_1-calibrado-a-las-grabaciones-originales-listo-para-mezcla" aria-label="Permalink to &quot;1. Calibrado a las Grabaciones Originales (Listo para Mezcla)&quot;">​</a></h3><p>En lugar de darte emulaciones crudas y sin pulir y dejarte luchar con la post-ecualización, hacemos el trabajo pesado de antemano. Cada plugin está meticulosamente afinado y calibrado estudiando la guitarra exacta y las respuestas dinámicas que se escuchan en los álbumes de estudio clásicos y grabaciones en vivo, asegurando que encajen inmediatamente en tu mezcla.</p><h3 id="_2-cpu-ultra-baja-y-maximo-rendimiento" tabindex="-1">2. CPU Ultra Baja y Máximo Rendimiento <a class="header-anchor" href="#_2-cpu-ultra-baja-y-maximo-rendimiento" aria-label="Permalink to &quot;2. CPU Ultra Baja y Máximo Rendimiento&quot;">​</a></h3><p>Creemos que tu computadora debe enfocarse en tu música, no en ejecutar gráficos pesados o bucles DSP ineficientes. Todas nuestras herramientas están construidas utilizando motores de audio altamente optimizados y código DSP ligero que ofrecen un rendimiento máximo con un consumo de CPU extremadamente bajo, lo que te permite ejecutar múltiples instancias sin problemas.</p><hr><h2 id="nuestra-mision" tabindex="-1">Nuestra Misión <a class="header-anchor" href="#nuestra-mision" aria-label="Permalink to &quot;Nuestra Misión&quot;">​</a></h2><p>Construir herramientas de audio virtuales boutique que suenen crudas, se sientan orgánicas y se aparten por completo del camino de tu inspiración.</p><p>Sin muros de registro, sin configuraciones infladas: solo conéctate, gira las perillas y toca.</p><hr><h2 id="🤝-colaboradores-y-amigos" tabindex="-1">🤝 Colaboradores y Amigos <a class="header-anchor" href="#🤝-colaboradores-y-amigos" aria-label="Permalink to &quot;🤝 Colaboradores y Amigos&quot;">​</a></h2><p>Main St Audio Labs cuenta con el apoyo de músicos apasionados, amantes del tono y amigos que aportan su oído, comentarios y experiencia a nuestros proyectos:</p><ul><li><strong>Claudio Crespino</strong> — Agradecimiento especial por su invaluable colaboración, pruebas y constante apoyo en el desarrollo y afinación de nuestras herramientas de audio.</li></ul>',22)),d(s),a[2]||(a[2]=e("hr",null,null,-1)),a[3]||(a[3]=e("h2",{id:"contacto-y-comentarios",tabindex:"-1"},[u("Contacto y Comentarios "),e("a",{class:"header-anchor",href:"#contacto-y-comentarios","aria-label":'Permalink to "Contacto y Comentarios"'},"​")],-1)),a[4]||(a[4]=e("p",null,"Siempre estamos escuchando. Si tienes alguna sugerencia, pistas de audio que quieras compartir, no dudes en copiar nuestro correo a continuación:",-1)),e("div",p,[a[0]||(a[0]=e("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),e("button",{class:"rock-copy-btn",onClick:i},c(o.value),1)]),a[5]||(a[5]=e("p",{style:{"margin-top":"2rem","margin-bottom":"1rem"}},"Si deseas apoyar nuestra investigación independiente y ayudarnos a mantener nuestros plugins gratuitos, puedes apoyarnos con Tarjeta, PayPal o Criptomonedas:",-1)),a[6]||(a[6]=e("div",null,[e("a",{href:"/es/support",class:"rock-btn rock-btn-primary",style:{display:"inline-block","text-align":"center"}},"Apoya el Laboratorio (Ko-fi / Crypto) ☕")],-1))])}}});export{f as __pageData,q as default};
